content.solution_code:
class StreamableContent {
  constructor(title) {
    this.title = title;
  }

  stream() {
    return `${this.title} is now streaming.`;
  }
}

class Movie extends StreamableContent {
  constructor(title, duration) {
    super(title);
    this.duration = duration;
  }

  stream() {
    return `Movie "${this.title}" (${this.duration} min) is playing. Enjoy!`;
  }
}

class SeriesEpisode extends StreamableContent {
  constructor(title, seriesTitle, episodeNumber) {
    super(title);
    this.seriesTitle = seriesTitle;
    this.episodeNumber = episodeNumber;
  }

  stream() {
    return `Episode ${this.episodeNumber} of "${this.seriesTitle}" - "${this.title}" is now available.`;
  }
}

class LiveEvent extends StreamableContent {
  constructor(title, date) {
    super(title);
    this.date = date;
  }

  stream() {
    return `LIVE: "${this.title}" is streaming now! (Event Date: ${this.date})`;
  }
}

